// Move the native landing-circle control once. Its line contact is a follower.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using Autodesk.AutoCAD.EditorInput;using Autodesk.AutoCAD.ApplicationServices;
using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class IndexAnchorV1 {
 public class Edit {public string handle,layout,layer;public double[][] expected_grips;public double[] anchor;}
 public class TestJob {public string input,input_sha256,output,receipt;public Edit[] indexes;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=50000000};
 static void Need(bool ok,string why){if(!ok)throw new InvalidOperationException(why);}
 static Point3d P(double[] p){Need(p!=null&&p.Length==3&&p.All(v=>!Double.IsNaN(v)&&!Double.IsInfinity(v)),"FINITE_POINT_REQUIRED");return new Point3d(p[0],p[1],p[2]);}
 static double[] A(Point3d p){return new[]{p.X,p.Y,p.Z};}
 static GripDataCollection Grips(Entity e){var g=new GripDataCollection();e.GetGripPoints(g,1,5,Vector3d.ZAxis,GetGripPointsFlags.GripPointsOnly);Need(g.Count==7,"SEVEN_GRIP_INDEX_REQUIRED");return g;}
 static double[][] Points(Entity e){return Grips(e).Cast<GripData>().Select(g=>A(g.GripPoint)).ToArray();}
 static object Prop(Entity e,string name){var c=e.AcadObject;return c.GetType().InvokeMember(name,BindingFlags.GetProperty,null,c,null);}
 static void ProtectedParts(Entity e,List<string> parts,int depth){Need(depth<8,"DISPLAY_DEPTH");var text=e as DBText;if(text!=null){parts.Add(J.Serialize(new{type=e.GetRXClass().Name,text=text.TextString,position=A(text.Position),alignment=A(text.AlignmentPoint),height=text.Height,width=text.WidthFactor,rotation=text.Rotation,style=text.TextStyleId.Handle.ToString()}));return;}var circle=e as Circle;if(circle!=null){parts.Add(J.Serialize(new{type="circle",center=A(circle.Center),radius=circle.Radius}));return;}if(e is Line||e is Polyline)return;var all=new DBObjectCollection();try{e.Explode(all);foreach(DBObject o in all){var p=o as Entity;if(p!=null)ProtectedParts(p,parts,depth+1);}}finally{foreach(DBObject o in all)o.Dispose();}}
 static string Protected(Entity e){var parts=new List<string>();ProtectedParts(e,parts,0);Need(parts.Count>=5,"INDEX_TEXT_AND_SYMBOL_REQUIRED");return J.Serialize(new{up=Prop(e,"UpText"),down=Prop(e,"DownText"),height=Prop(e,"Height"),scale=Prop(e,"Scale"),rotation=Prop(e,"LayoutRotation"),owner=e.OwnerId.Handle.ToString(),layer=e.Layer,color=e.Color.ToString(),lt=e.Linetype,lw=(int)e.LineWeight,parts=parts});}
 public static double Topology(Entity e){var g=Grips(e);var all=new DBObjectCollection();try{e.Explode(all);var lines=all.Cast<DBObject>().OfType<Line>().ToArray();var rings=all.Cast<DBObject>().OfType<Polyline>().ToArray();Func<Line,Point3d,Point3d,bool> connects=(l,a,b)=>(l.StartPoint.DistanceTo(a)<1e-7&&l.EndPoint.DistanceTo(b)<1e-7)||(l.StartPoint.DistanceTo(b)<1e-7&&l.EndPoint.DistanceTo(a)<1e-7);Need(all.Count==6&&lines.Length==2&&rings.Length==1&&lines.Any(l=>connects(l,g[0].GripPoint,g[1].GripPoint))&&lines.Any(l=>connects(l,g[3].GripPoint,g[1].GripPoint)),"SINGLE_LANDING_CIRCLE_INDEX_TOPOLOGY_REQUIRED");var p=rings[0];Need(p.Closed&&p.NumberOfVertices==2&&Math.Abs(p.GetBulgeAt(0)-1)<1e-8&&Math.Abs(p.GetBulgeAt(1)-1)<1e-8,"LANDING_CIRCLE_REQUIRED");var pa=p.GetPoint3dAt(0);var pb=p.GetPoint3dAt(1);var center=pa+(pb-pa)*.5;double radius=pa.DistanceTo(pb)*.5;Need(center.DistanceTo(g[2].GripPoint)<1e-7&&Math.Abs(g[3].GripPoint.DistanceTo(center)-radius)<1e-7,"LANDING_GRIP_ROLES_CHANGED");var v=g[1].GripPoint-center;Need(v.Length>radius+1e-7&&g[3].GripPoint.DistanceTo(center+v.GetNormal()*radius)<1e-7,"CONTACT_NOT_NATIVE_RADIAL_FOLLOWER");return radius;}finally{foreach(DBObject o in all)o.Dispose();}}
 public static object Apply(Database db,Edit[] edits,Action mutate){Need(edits!=null&&edits.Length>0&&edits.All(i=>i!=null&&!String.IsNullOrEmpty(i.handle))&&edits.Select(i=>i.handle.ToUpperInvariant()).Distinct().Count()==edits.Length,"UNIQUE_INDEX_TARGETS_REQUIRED");var selected=new HashSet<string>(edits.Select(i=>i.handle),StringComparer.OrdinalIgnoreCase);var touched=new HashSet<string>();var result=new List<object>();ObjectEventHandler modified=(s,e)=>{if(e.DBObject is Entity&&!selected.Contains(e.DBObject.Handle.ToString()))touched.Add(e.DBObject.Handle.ToString());};ObjectErasedEventHandler erased=(s,e)=>{if(e.Erased&&e.DBObject is Entity)touched.Add(e.DBObject.Handle.ToString());};
  using(var tr=db.TransactionManager.StartTransaction()){
   foreach(var i in edits){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.handle,16)),0),OpenMode.ForRead);Need(e.GetRXClass().Name=="TDbSymbIndexPointer"&&e.Layer==i.layer&&e.OwnerId==BoundCadEditsV1.Space(tr,db,i.layout),"EXACT_NATIVE_INDEX_OWNER_REQUIRED");var g=Grips(e);Need(i.expected_grips!=null&&i.expected_grips.Length==7,"EXPECTED_SEVEN_GRIPS_REQUIRED");for(int k=0;k<7;k++)Need(g[k].GripPoint.DistanceTo(P(i.expected_grips[k]))<1e-8,"EXPECTED_GRIP_CHANGED");P(i.anchor);Topology(e);Protected(e);}
   db.ObjectModified+=modified;db.ObjectAppended+=modified;db.ObjectErased+=erased;
   try{foreach(var i in edits){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.handle,16)),0),OpenMode.ForRead);string kept=Protected(e);double radius=Topology(e);var before=Points(e);var g=Grips(e);var delta=P(i.anchor)-g[2].GripPoint;int moves=0;if(delta.Length>1e-8){mutate();e.UpgradeOpen();var one=new GripDataCollection();one.Add(g[2]);e.MoveGripPointsAt(one,delta,(MoveGripPointsFlags)0);e.RecordGraphicsModified(true);moves=1;}var after=Points(e);Need(P(after[2]).DistanceTo(P(i.anchor))<1e-8,"ANCHOR_MOVE_MISMATCH");foreach(int k in new[]{0,1,4,5,6})Need(P(before[k]).DistanceTo(P(after[k]))<1e-8,"PROTECTED_GRIP_MOVED");Need(kept==Protected(e)&&Math.Abs(radius-Topology(e))<1e-8,"INDEX_CONTENT_OR_TOPOLOGY_CHANGED");result.Add(new{handle=i.handle,before=before,after=after,native_control_moves=moves,control_grip=2,automatic_follower_grip=3,text_index_style_preserved=true});}Need(touched.Count==0,"UNSELECTED_ENTITY_CHANGED");tr.Commit();Need(touched.Count==0,"UNSELECTED_ENTITY_CHANGED_ON_COMMIT");}finally{db.ObjectModified-=modified;db.ObjectAppended-=modified;db.ObjectErased-=erased;}
  }return new{indexes=result,unselected_entity_write_guard=true};
 }
 static string Snapshot(Database db,Edit[] edits){var rows=new List<object>();using(var tr=db.TransactionManager.StartTransaction())foreach(var i in edits){var e=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(i.handle,16)),0),OpenMode.ForRead);rows.Add(new{handle=i.handle,grips=Points(e),kept=Protected(e),radius=Topology(e)});}return J.Serialize(rows);}
 [CommandMethod("HLCADINDEXANCHORTESTV1",CommandFlags.Session)]public void Test(){var original=App.DocumentManager.MdiActiveDocument;var olddb=HostApplicationServices.WorkingDatabase;var a=original.Editor.GetString(new PromptStringOptions("\nIndex test job: "){AllowSpaces=true});if(a.Status!=PromptStatus.OK)return;TestJob job=null;Document d=null;try{job=J.Deserialize<TestJob>(File.ReadAllText(a.StringResult.Trim('"')));Need(BoundCadEditsV1.Hash(job.input)==job.input_sha256&&!File.Exists(job.output)&&!File.Exists(job.receipt),"TEST_FILE_IDENTITY");var stage=job.output+".staging.dwg";File.Copy(job.input,stage,false);d=App.DocumentManager.Open(stage,false);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;object changes;string expected;using(d.LockDocument()){changes=Apply(d.Database,job.indexes,()=>{});expected=Snapshot(d.Database,job.indexes);d.Database.SaveAs(job.output,DwgVersion.AC1032);}App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=olddb;d.CloseAndDiscard();d=App.DocumentManager.Open(job.output,true);App.DocumentManager.MdiActiveDocument=d;HostApplicationServices.WorkingDatabase=d.Database;using(d.LockDocument())Need(CadValueCompareV1.Json(expected,Snapshot(d.Database,job.indexes)),"SAVE_REOPEN_MISMATCH");File.WriteAllText(job.receipt,J.Serialize(new{status="ISOLATED_NATIVE_INDEX_ANCHOR_VERIFIED",changes=changes,save_reopen_verified=true,source_unchanged=BoundCadEditsV1.Hash(job.input)==job.input_sha256,output=job.output,sha256=BoundCadEditsV1.Hash(job.output)}));}catch(System.Exception ex){if(job!=null&&!File.Exists(job.receipt))File.WriteAllText(job.receipt,J.Serialize(new{status="INDEX_TEST_FAILED",error=ex.ToString()}));}finally{App.DocumentManager.MdiActiveDocument=original;HostApplicationServices.WorkingDatabase=olddb;if(d!=null)d.CloseAndDiscard();}}
}
